import React, { useState } from 'react';
import '../styles/DashboardPage.css';
// the below code is for the components and will code later after finish all frontend part
// import IssueTable from './components/IssueTable';

const DashboardPage = () => {
  // Mock data
  const [statusFilter, setStatusFilter] = useState('All');

  const issues = [
    { id: 1, title: 'Login bug', status: 'Open', date: '2025-06-01' },
    { id: 2, title: 'Conflict in R&D Team', status: 'In Progress', date: '2025-06-01' },
    { id: 3, title: 'Conflict in R&D Team', status: 'Resolved', date: '2025-06-02' }
  ];

  const filteredIssues = statusFilter === 'All' 
    ? issues 
    : issues.filter(issue => issue.status === statusFilter);

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1>Issue Management System</h1>
        <p className="welcome-message">Welcome, testUser</p>
      </header>

      <div className="dashboard-controls">
        <button className="new-issue-btn">Submit New Issue</button>
        <div className="filter-control">
          <label>Filter by Status:</label>
          <select>
            <option>All</option>
            <option>Open</option>
            <option>In Progress</option>
            <option>Resolved</option>
          </select>
        </div>
      </div>

      {/* issue tables */}
      <table className="issue-table">
        <thead>
          <tr>
            <th>Title</th>
            <th>Status</th>
            <th>Date</th>
          </tr>
        </thead>
        <tbody>
          {filteredIssues.map(issue => (
            <tr key={issue.id}>
              <td>{issue.title}</td>
              <td>
                <span className={`status ${issue.status.toLowerCase().replace(' ', '-')}`}>
                  {issue.status}
                </span>
              </td>
              <td>{issue.date}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default DashboardPage;
